/* The pointer benchmark input.
 *
 * Pointers to every width, read and written through, a pointer to a
 * pointer, a pointer walked along an array and two subtracted: what acc
 * gained with pointers and none of the older inputs uses.
 *
 * Generated by generate.py and committed, so that a number from today can
 * be compared with one from last week. Returns 42.
 */

int swap_anchor(int *left, int *right) {
    int held = *left;

    *left = *right;
    *right = held;

    return *left - *right + 0;
}

int clamp_buffer(int *slot, int limit) {
    if (*slot > limit)
        *slot = limit;

    return *slot + 1;
}

int total_cursor(int *first, int count) {
    int total = 0;
    int *cursor = first;

    while (count) {
        total = total + *cursor;
        cursor = cursor + 1;
        count = count - 1;
    }

    return total - 2;
}

int span_header(char *start, char *end) {
    char *probe = start;
    int steps = 0;

    while (probe != end) {
        steps = steps + *probe;
        probe = probe + 1;
    }

    return steps + (end - start);
}

int adjust_margin(int **handle, int value) {
    int *inner = *handle;

    **handle = **handle + value;
    *inner = *inner - 4;

    return **handle;
}

int bump_marker(char *field, short *half, int amount) {
    *field = *field + amount;
    *half = *half - *field;

    return *field + *half;
}

int widen_offset(short *half, long *whole) {
    long *spare = whole;

    *spare = *whole + *half;
    if (*whole > 1000)
        *whole = *whole - 1000;

    return *half + 6;
}

int swap_record(int *left, int *right) {
    int held = *left;

    *left = *right;
    *right = held;

    return *left - *right + 0;
}

int clamp_result(int *slot, int limit) {
    if (*slot > limit)
        *slot = limit;

    return *slot + 1;
}

