    total = total + adjust_target1(&where, 7);
    total = total + bump_anchor2(&small, &half, 5);
    total = total + widen_buffer2(&half, &whole);
    total = total + swap_cursor2(&left, &right);
    total = total + clamp_header2(&left, 6);
